def chain_chain(chain):
    chain = list(chain)
    chain.sort(key=lambda x: (-len(x), x))
    result = []
    for i in range(len(chain) - 1):
        if chain[i][1] == chain[i+1][0]:
            result.append(chain[i][0])
            result.append(chain[i+1][0])
    result.append(chain[-1][0])
    return ','.join(result)

